def my_decorator(func):
    def wrapper():
        print('قبل از تابع')
        func()
        print('بعد از تابع')
    return wrapper

@my_decorator
def say_hello():
    print('سلام!')

say_hello()

def repeat(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            for _ in range(times):
                func(*args, **kwargs)
        return wrapper
    return decorator

@repeat(3)
def greet():
    print('سلام!')

greet()

